// Normalise the Gmail payload and build the Claude request (JSON built here: n8n expressions stop at the first '}}').
const CONTEXT = $env.BUSINESS_CONTEXT || 'Small professional-services firm. Office hours Mon-Fri 9-5. Replies are warm, brief, and never promise prices, legal outcomes, or deadlines. Anything about invoices, refunds, complaints, legal threats, or personal data goes to a human.';
const SYSTEM = `You triage a shared inbox for this business:\n${CONTEXT}\n\nClassify each email into exactly one category: support (existing customer question), sales (new business enquiry), billing (invoices, payments, refunds), spam (unsolicited marketing, phishing, irrelevant), or needs_human (angry, legal, sensitive, ambiguous, or anything you are not confident about). For support and sales only, write a short reply draft in the business voice that answers what you safely can and offers a next step; never invent facts, prices, or commitments. For every other category draft_reply is null. Confidence below 0.7 means needs_human.`;
const SCHEMA = { type: 'object', additionalProperties: false,
  required: ['category','confidence','summary','urgency','draft_reply','reason'],
  properties: { category: { type: 'string', enum: ['support','sales','billing','spam','needs_human'] }, confidence: { type: 'number', minimum: 0, maximum: 1 },
    summary: { type: 'string' }, urgency: { type: 'string', enum: ['low','normal','high'] }, draft_reply: { type: ['string','null'] }, reason: { type: 'string' } } };
return $input.all().map(item => {
  const j = item.json;
  const h = j.headers || {};
  const email = { id: j.id, threadId: j.threadId, from: h.from || j.from?.value?.[0]?.address || j.From || '', subject: h.subject || j.subject || j.Subject || '', date: h.date || j.date || '',
    body: String(j.text || j.textPlain || j.snippet || '').slice(0, 8000) };
  const request = { model: $env.TRIAGE_MODEL || 'claude-sonnet-5', max_tokens: 1024, system: SYSTEM,
    messages: [{ role: 'user', content: JSON.stringify({ from: email.from, subject: email.subject, date: email.date, body: email.body }) }],
    output_config: { format: { type: 'json_schema', schema: SCHEMA } } };
  return { json: { email, request } };
});

// Parse the decision and apply policy the model cannot override: only support/sales get drafts, low confidence escalates.
const src = $('Normalise + build request').all();
return $input.all().map((item, i) => {
  const email = src[i].json.email;
  let t;
  try {
    const block = (item.json.content || []).find(b => b.type === 'text');
    if (!block) throw new Error('no text block (stop_reason=' + item.json.stop_reason + ')');
    t = JSON.parse(block.text);
  } catch (e) {
    t = { category: 'needs_human', confidence: 0, summary: 'triage failed: ' + e.message, urgency: 'normal', draft_reply: null, reason: 'parse error' };
  }
  if (!['support','sales'].includes(t.category)) t.draft_reply = null;
  if (t.confidence < 0.7 && t.category !== 'spam') { t.category = 'needs_human'; t.draft_reply = null; }
  const labelEnv = { support: 'TRIAGE_LABEL_SUPPORT', sales: 'TRIAGE_LABEL_SALES', billing: 'TRIAGE_LABEL_BILLING', spam: 'TRIAGE_LABEL_SPAM', needs_human: 'TRIAGE_LABEL_NEEDS_HUMAN' }[t.category];
  return { json: { ...email, ...t, labelId: $env[labelEnv] || '', shouldDraft: ['support','sales'].includes(t.category) && !!t.draft_reply } };
});

// Digest from today's labelled mail. Labels were applied by the live flow, so no second model call is needed.
const names = { support: $env.TRIAGE_LABEL_SUPPORT, sales: $env.TRIAGE_LABEL_SALES, billing: $env.TRIAGE_LABEL_BILLING, needs_human: $env.TRIAGE_LABEL_NEEDS_HUMAN };
const cat = (labels = []) => Object.entries(names).find(([, id]) => id && labels.includes(id))?.[0] || 'unlabelled';
const rows = $input.all().map(i => ({ from: i.json.From || i.json.from || '', subject: i.json.Subject || i.json.subject || '', category: cat(i.json.labelIds) }));
const needs = rows.filter(r => r.category === 'needs_human' || r.category === 'billing');
const drafts = rows.filter(r => r.category === 'support' || r.category === 'sales');
const counts = rows.reduce((a, r) => (a[r.category] = (a[r.category] || 0) + 1, a), {});
const lines = [`Inbox digest: ${rows.length} emails, ${needs.length} need you, ${drafts.length} drafts waiting`];
if (needs.length) { lines.push('', 'NEEDS YOU'); needs.forEach(r => lines.push(`  [${r.category}] ${r.from}: ${r.subject}`)); }
if (drafts.length) { lines.push('', 'DRAFTS WAITING FOR APPROVAL (in Gmail Drafts)'); drafts.forEach(r => lines.push(`  (${r.category}) ${r.from}: ${r.subject}`)); }
lines.push('', 'BY CATEGORY  ' + Object.entries(counts).map(([k, v]) => `${k} ${v}`).join(', '));
return [{ json: { text: lines.join('\n'), count: rows.length } }];
